node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(ws);

// Check if PROD-2028EE already exists
const exists = data.find(r => r['Product ID'] === 'PROD-2028EE');
console.log('PROD-2028EE exists?', !!exists);

// Add new row with expanded columns
const newRow = {
  'Product ID': 'PROD-2028EE',
  'Name': 'Magnetic Wireless Charging Stand',
  'Category': 'electronics',
  'Price': 4499,
  'In Stock': 'Yes',
  'Brand': 'VoltForge',
  'Stock Quantity': 96,
  'Shipping Days': 3,
  'Variants': 'None'
};

// Update all existing rows to include the new columns (with empty/default values)
const updatedData = data.map(row => ({
  ...row,
  'Brand': row['Brand'] || '',
  'Stock Quantity': row['Stock Quantity'] || '',
  'Shipping Days': row['Shipping Days'] || '',
  'Variants': row['Variants'] || ''
}));

updatedData.push(newRow);

// Write back
const newWs = XLSX.utils.json_to_sheet(updatedData, {
  header: ['Product ID', 'Name', 'Category', 'Price', 'In Stock', 'Brand', 'Stock Quantity', 'Shipping Days', 'Variants']
});
wb.Sheets[wb.SheetNames[0]] = newWs;
XLSX.writeFile(wb, '/workspace/testbed/data/product_inventory.xlsx');
console.log('File updated successfully. Total rows:', updatedData.length);
"

